-- What the Credits window draws (pure, tested by creditsview_test.lua). The data is ChaosCreditsData from
-- credits_data.lua, generated by client/tools/gen_credits.py from docs/CREDITS.md: sections {title, pt, note,
-- entries = {{name, author, licence, credit, use, source}}}. Headings go through tr() (pt_br.lua holds each heading,
-- tools/ci/check_credits.py checks it); names, authors and credit lines are shown as written.
CreditsView = {}

CreditsView.COLORS = {
  intro = '#d6c9ae', section = '#e8b84a', note = '#a89c88', name = '#f6cf72', line = '#d6c9ae', credit = '#ffe7a8'
}

local function identity(text, ...)
  if select('#', ...) > 0 then return string.format(text, ...) end
  return text
end

-- {style, text, color} in drawing order; tr defaults to the identity (tests, a client without the locale module)
function CreditsView.blocks(data, tr)
  tr = tr or identity
  local C = CreditsView.COLORS
  local out = {}
  local function add(style, text)
    if type(text) == 'string' and text ~= '' then
      out[#out + 1] = { style = style, text = text, color = C[style] }
    end
  end
  add('intro', tr('Cinders of Chaos is made with the work of these people and projects. Thank you!'))
  for _, section in ipairs(type(data) == 'table' and data or {}) do
    if type(section) == 'table' and type(section.title) == 'string' then
      add('section', tr(section.title))
      add('note', section.note)
      for _, e in ipairs(section.entries or {}) do
        add('name', e.name)
        if e.author then add('line', tr('Author: %s', e.author)) end
        if e.credit then add('credit', e.credit) end
        if e.licence then add('line', tr('Licence: %s', e.licence)) end
        if e.use then add('line', tr('Used for: %s', e.use)) end
        if e.source then add('line', tr('Source: %s', e.source)) end
      end
    end
  end
  return out
end

-- the required credit lines, word for word (the licence asks for them)
function CreditsView.requiredCredits(data)
  local out = {}
  for _, section in ipairs(type(data) == 'table' and data or {}) do
    for _, e in ipairs(section.entries or {}) do
      if e.credit then out[#out + 1] = e.credit end
    end
  end
  return out
end
